import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Badge from 'flarum/common/components/Badge';
import Button from 'flarum/common/components/Button';
import LinkButton from 'flarum/common/components/LinkButton';
import Tooltip from 'flarum/common/components/Tooltip';
import Discussion from 'flarum/common/models/Discussion';
import CommentPost from 'flarum/forum/components/CommentPost';
import SessionDropdown from 'flarum/forum/components/SessionDropdown';
import UserControls from 'flarum/forum/utils/UserControls';
import classList from 'flarum/common/utils/classList';
import EndorseModal from './components/EndorseModal';
import { expertTags, t, tText } from '../common/utils/experts';
export { default as extend } from './extend';

/** Tags da discussão em que o autor do post é especialista. */
function postExpertTags(post) {
  const discussion = post.discussion();
  const tags = discussion ? discussion.tags?.() || [] : [];
  return post.contentType() === 'comment' && !post.isHidden() ? expertTags(post.user(), tags) : [];
}
app.initializers.add('ramon-tag-experts', () => {
  // O selo ao lado do nome e a classe no post; os grupos já vêm com o post.
  extend(CommentPost.prototype, 'headerItems', function (items) {
    const tags = postExpertTags(this.attrs.post);
    if (!tags.length) return;
    const tooltip = tText('forum.post.expert_tooltip', {
      tags: tags.map(tag => tag.name()).join(', ')
    });
    items.add('tagExpert', m(Tooltip, {
      text: tooltip
    }, m("span", {
      className: "TagExpertBadge",
      tabindex: "0",
      "aria-label": tooltip
    }, m("i", {
      className: "fas fa-user-graduate",
      "aria-hidden": "true"
    }), m("span", {
      className: "TagExpertBadge-label"
    }, t('forum.post.expert_badge')))), 90);
  });
  extend(CommentPost.prototype, 'elementAttrs', function (attrs) {
    if (postExpertTags(this.attrs.post).length) {
      attrs.className = classList(attrs.className, 'Post--tagExpert');
    }
  });

  // Discussão respondida por especialista: selo na lista e na página.
  extend(Discussion.prototype, 'badges', function (items) {
    if (this.attribute('expertPostNumber')) {
      items.add('tagExpertReply', m(Badge, {
        type: "tagExpertReply",
        icon: "fas fa-user-graduate",
        label: t('forum.discussion.expert_reply_badge'),
        tabindex: "0"
      }), 5);
    }
  });
  extend(UserControls, 'userControls', function (items) {
    for (var _len = arguments.length, args = new Array(_len > 1 ? _len - 1 : 0), _key = 1; _key < _len; _key++) {
      args[_key - 1] = arguments[_key];
    }
    const user = args[0];
    const actor = app.session.user;
    if (!actor || actor === user || !app.forum.attribute('canEndorseTagExperts')) return;
    items.add('tagExpertEndorse', m(Button, {
      icon: "fas fa-user-graduate",
      onclick: () => app.modal.show(EndorseModal, {
        user
      })
    }, t('forum.user_controls.endorse_button')));
  });
  extend(SessionDropdown.prototype, 'items', function (items) {
    if (!app.forum.attribute('canReviewTagExperts')) return;
    items.add('tagExpertSuggestions', m(LinkButton, {
      icon: "fas fa-user-graduate",
      href: app.route('tagExperts.suggestions')
    }, t('forum.header.suggestions_button')), 45);
  });

  // A grade de notificações é carregada sob demanda: extend pelo nome.
  extend('flarum/forum/components/NotificationGrid', 'notificationTypes', function (items) {
    items.add('tagExpertApproved', {
      name: 'tagExpertApproved',
      icon: 'fas fa-user-graduate',
      label: t('forum.settings.notify_approved_label')
    });
  });
});